<script setup>
import {computed,onMounted,onUnmounted,ref} from 'vue';
import catalog from '@/sheep/api/pharmacy/server';
import {formatDate} from '@/sheep/api/pharmacy/common';
import trade from './trade.js';
import {identity} from './session.js';
import {sameIdentity} from './guards.js';
import {localAcceptance} from './config.js';
import {yuanMoney,selectedRows,estimate,canCancel,canReceive,canMockPay,orderState,expired} from './trade-core.js';
import TradeLine from './TradeLine.vue';
const props=defineProps({route:String,orderId:String,user:Object});const emit=defineEmits(['login','notice']);
const rows=ref([]),addresses=ref([]),stock=ref({}),stockError=ref(''),store=ref(null),loading=ref(false),busy=ref(false),error=ref(''),orders=ref([]),total=ref(0),page=ref(1),status=ref(''),order=ref(null),capability=ref(false),orderType=ref(0),addressId=ref(null),remark=ref(''),attempt=ref(null),confirmation=ref(null);
let disposed=false,generation=0;const owner=identity();
const current=()=>!disposed&&!!props.user&&sameIdentity(owner,identity());
const selected=computed(()=>selectedRows(rows.value)),amount=computed(()=>estimate(selected.value));
const canCheckout=computed(()=>selected.value.length>0&&!selected.value.some(r=>r.isRx===1)&&!busy.value&&!loading.value);
const createBlocked=computed(()=>busy.value||loading.value||!canCheckout.value||orderType.value===1&&!addressId.value||attempt.value?.pending||attempt.value?.unknown||!!attempt.value?.id);
const title=computed(()=>({cart:'购物车',checkout:'确认订单',orders:'我的订单','order-detail':'订单详情'}[props.route]));
function notify(text){if(current())emit('notice',text);}
async function loadCart(){const list=await trade.cart(store.value.id);if(!current())return;rows.value=list;stockError.value='';if(!list.length){stock.value={};return;}try{const quantities=await trade.available(store.value.id,list.map(r=>r.drugId));if(current())stock.value=Object.fromEntries(quantities.map(r=>[r.drugId,r.qtyAvail]));}catch(e){if(current())stockError.value='可售库存暂时无法读取，请以服务端复核为准';}}
async function load(){if(!props.user)return;const g=++generation;loading.value=true;error.value='';try{if(!catalog.store.id)await catalog.refreshStore();if(!current()||g!==generation)return;store.value={...catalog.store};if(props.route==='cart'||props.route==='checkout'){await loadCart();if(props.route==='checkout'){const list=await trade.addresses();if(!current()||g!==generation)return;addresses.value=list;addressId.value=list.find(a=>a.defaultStatus)?.id||list[0]?.id||null;attempt.value=trade.creation();}}else if(props.route==='orders'){const result=await trade.orders(page.value,status.value);if(!current()||g!==generation)return;orders.value=result.list;total.value=result.total;}else{if(!/^\d+$/.test(props.orderId||''))throw Error('订单链接无效');const result=await trade.order(Number(props.orderId));if(!current()||g!==generation)return;order.value=result;capability.value=false;const allowed=await trade.capability();if(current()&&g===generation)capability.value=allowed;}}catch(e){if(current()&&g===generation)error.value=e.message;}finally{if(current()&&g===generation)loading.value=false;}}
async function mutate(operation,success){if(busy.value||!current())return;busy.value=true;error.value='';try{await operation();if(!current())return;await loadCart();if(success)notify(success);}catch(e){if(current())error.value=e.message;}finally{if(current())busy.value=false;}}
function beginCheckout(){try{trade.beginCheckout();location.hash='checkout';}catch(e){error.value=e.message;}}
async function placeOrder(){if(createBlocked.value||!current())return;busy.value=true;error.value='';try{const id=await trade.create({storeId:store.value.id,orderType:orderType.value,addressId:addressId.value,remark:remark.value});if(!current())return;location.hash='order-detail?id='+id;}catch(e){if(current()){attempt.value=trade.creation();error.value=attempt.value?.unknown?'创建结果暂时无法确认。请先到订单列表核对，不要重复提交。':e.message;}}finally{if(current())busy.value=false;}}
function askAction(kind,id){confirmation.value={kind,id};}
async function confirmAction(){const action=confirmation.value;if(!action||busy.value||!current())return;confirmation.value=null;busy.value=true;error.value='';try{if(action.kind==='remove'){await trade.remove(store.value.id,action.id);if(current())await loadCart();}else{if(action.kind==='cancel')await trade.cancel(action.id);else if(action.kind==='receive')await trade.receive(action.id);else await trade.simulate(action.id,localAcceptance);if(current())await load();}if(current())notify('操作已由后端确认');}catch(e){if(current())error.value=e.message;}finally{if(current())busy.value=false;}}
function changePage(n){page.value=n;load();window.scrollTo(0,0);}
onMounted(load);onUnmounted(()=>{disposed=true;generation++;});
</script>
<template><main class="customer-page"><div class="breadcrumb"><a href="#catalog">找药购药</a><Icon name="chevron-right"/><span>{{title}}</span></div><div class="customer-title"><div><div class="eyebrow">FIRSTSUN / SHOPPING</div><h1>{{title}}</h1><p>{{route==='checkout'?'提交前金额为估算，实际应付以创建后的订单为准。':'查看本人商品和订单，数据由当前服务返回。'}}</p></div><a v-if="route==='cart'" class="btn" href="#catalog">继续选购</a><a v-else class="btn" href="#cart">查看购物车</a></div>
<div v-if="!user" class="empty-state"><Icon name="circle-user-round"/><h2>登录后继续</h2><p>购物车、地址与订单仅本人可见。</p><button class="btn primary" @click="emit('login')">登录会员账号</button></div><template v-else><div v-if="error" class="error-panel trade-error" role="alert">{{error}}<button v-if="!attempt?.unknown" class="btn link" :disabled="loading||busy" @click="load()">重新读取</button><a v-else class="btn link" href="#orders">去订单列表核对</a></div><div v-if="loading" class="skeleton" aria-busy="true" aria-label="正在读取"></div><template v-else>
<template v-if="route==='cart'"><div v-if="rows.length" class="commerce-layout"><section class="paper"><div class="paper-head"><h2>{{store?.name}} <span class="small muted">门店 #{{store?.id}}</span></h2><span class="small muted">{{rows.length}} 款商品</span></div><TradeLine v-for="r in rows" :key="r.id" :row="r" editable :busy="busy" :stock="stock[r.drugId]" @quantity="qty=>mutate(()=>trade.quantity(store.id,r.id,qty))" @select="flag=>mutate(()=>trade.select(store.id,r.id,flag))" @remove="askAction('remove',r.id)"/><div class="paper-bottom"><Icon name="shield-check"/>只显示当前门店的购物车行，其他门店记录不受本页操作影响。</div></section><aside class="summary-box"><h2>商品估算</h2><dl><dt>已选</dt><dd>{{selected.reduce((s,r)=>s+r.qty,0)}} 件</dd><dt>商品金额</dt><dd>¥{{yuanMoney(amount)}}</dd></dl><p v-if="stockError" role="status">{{stockError}}</p><p v-if="selected.some(r=>r.isRx===1)" class="trade-warm">已选处方药不能走普通结算，请先取消勾选。</p><div class="summary-total"><span>商品小计（估算）</span><span class="price">¥{{yuanMoney(amount)}}</span></div><button class="btn primary full" :disabled="!canCheckout" @click="beginCheckout">去结算 <Icon name="arrow-right"/></button><p>优惠、运费、可用量及最终应付均以服务端为准。</p></aside></div><div v-else-if="!error" class="empty-state"><Icon name="shopping-bag"/><h2>当前门店购物车为空</h2><p>可以先浏览非处方商品，核对详情后加入购物车。</p><a class="btn primary" href="#catalog">去找药</a></div></template>
<template v-else-if="route==='checkout'"><div v-if="selected.length" class="commerce-layout"><div class="stack"><section class="paper pad"><h2>收货方式</h2><div class="choice-row"><button class="choice" :class="{active:orderType===0}" :disabled="busy" @click="orderType=0"><Icon name="store"/><strong>到店自提</strong><span>由门店工作人员核销</span></button><button class="choice" :class="{active:orderType===1}" :disabled="busy" @click="orderType=1"><Icon name="truck"/><strong>门店配送</strong><span>选择本人已有地址</span></button></div><div v-if="orderType===0" class="delivery-address"><Icon name="map-pin"/><div><strong>{{store?.name}} · 门店 #{{store?.id}}</strong><p>{{store?.address||'门店地址暂未提供'}}</p></div></div><template v-else><div v-if="addresses.length" class="address-options"><label v-for="a in addresses" :key="a.id" class="address-option" :class="{active:addressId===a.id}"><input v-model="addressId" type="radio" name="address" :value="a.id" :disabled="busy"><span><strong>{{a.name}} · {{a.mobile}}</strong><span>{{a.detailAddress}}</span></span><span v-if="a.defaultStatus" class="tag neutral">默认</span></label></div><div v-else class="notice-panel">暂无本人收货地址。本批不提供地址新增/编辑，请选择到店自提。</div></template></section><section class="paper"><div class="paper-head"><h2>商品清单</h2><span class="small muted">门店 #{{store?.id}}</span></div><TradeLine v-for="r in selected" :key="r.id" :row="{...r,price:r.memberPrice??r.retailPrice,lineAmount:estimate([r])}"/></section><section class="paper pad"><label class="form-field">订单备注<textarea v-model="remark" maxlength="200" :disabled="busy" placeholder="选填，请勿填写敏感信息"></textarea></label></section></div><aside class="summary-box"><h2>提交前核对</h2><dl><dt>商品小计（估算）</dt><dd>¥{{yuanMoney(amount)}}</dd><dt>优惠 / 运费</dt><dd>以服务端订单为准</dd><dt>积分使用</dt><dd>本批不使用积分</dd></dl><p v-if="selected.some(r=>r.isRx===1)" class="trade-warm">处方药不可在本批结算。</p><div v-if="attempt?.unknown||attempt?.pending" class="error-panel">上一笔创建结果尚未确认，请先核对订单列表，勿重复提交。</div><a v-if="attempt?.id" class="btn full" :href="'#order-detail?id='+attempt.id">查看已创建订单</a><button class="btn primary full" :disabled="createBlocked" @click="placeOrder">{{busy?'正在提交…':'创建订单'}}</button><a v-if="attempt?.unknown" class="btn link full" href="#orders">去订单列表核对</a><p>提交成功后显示服务器计算的最终应付。本页不会自动重试创建请求。</p></aside></div><div v-else-if="!error" class="empty-state"><h2>没有待结算的当前门店商品</h2><a class="btn primary" href="#cart">返回购物车</a></div></template>
<template v-else-if="route==='orders'"><div class="customer-tabs"><button v-for="tab in [['','全部'],['0','待支付'],['1','待拣货'],['2','拣货中'],['3','待自提 / 收货'],['4','已完成'],['-1','已取消']]" :key="tab[0]" :class="{active:status===tab[0]}" :disabled="busy||loading" @click="status=tab[0];page=1;load()">{{tab[1]}}</button></div><section v-for="o in orders" :key="o.id" class="paper order-card" :data-order-id="o.id"><div class="paper-head"><span class="small muted">{{formatDate(o.createTime)}}　{{o.orderNo}}</span><span class="state-tag">{{orderState(o)}}</span></div><TradeLine v-for="r in o.lines" :key="r.id" :row="r"/><div class="order-bottom"><span class="small muted">{{o.orderType===0?'到店自提':'门店配送'}} · 门店 #{{o.storeId}} · 支付{{o.payStatus===1?'已完成':o.payStatus===2?'已退款':'未完成'}}</span><span>实际应付 <strong>¥{{yuanMoney(o.payableAmount)}}</strong></span><a class="btn" :href="'#order-detail?id='+o.id">查看详情</a></div></section><div v-if="!orders.length&&!error" class="empty-state"><Icon name="package-open"/><h2>暂无此类订单</h2><p>试试其他状态，或前往购药页。</p></div><nav v-if="total>6" class="pagination" aria-label="订单分页"><button :disabled="page<=1" @click="changePage(page-1)"><Icon name="chevron-left"/></button><span>{{page}} / {{Math.ceil(total/6)}} · 共 {{total}} 笔</span><button :disabled="page*6>=total" @click="changePage(page+1)"><Icon name="chevron-right"/></button></nav></template>
<template v-else-if="order"><section class="order-status" :data-order-id="order.id"><span class="large-status-icon"><Icon :name="order.payStatus===0?'wallet':'package-check'"/></span><div><h2>{{orderState(order)}}</h2><p>{{order.orderNo}} · 订单 #{{order.id}}</p><p>支付状态：{{order.payStatus===0?'未支付':order.payStatus===1?'已支付':order.payStatus===2?'已退款':'待核实'}}<span v-if="order.payStatus===0&&expired(order)"> · 已超过付款截止时间</span></p></div><button class="btn" :disabled="busy" @click="load()"><Icon name="refresh-cw"/>刷新订单</button></section><section class="paper"><div class="paper-head"><h2>订单商品快照</h2><span class="small muted">门店 #{{order.storeId}}</span></div><TradeLine v-for="r in order.lines" :key="r.id" :row="r"/></section><div class="info-columns"><section class="paper pad"><h3>履约信息</h3><dl class="details-list"><dt>履约门店</dt><dd>#{{order.storeId}}</dd><dt>收货方式</dt><dd>{{order.orderType===0?'到店自提':'门店配送'}}</dd><template v-if="order.orderType===1"><dt>地址快照</dt><dd>{{order.addressSnapshot||'服务端未提供'}}</dd></template><template v-else><dt>取货码</dt><dd class="pickup-code">{{order.pickupCode||'服务端未提供'}}</dd></template><dt>创建时间</dt><dd>{{formatDate(order.createTime)||'未提供'}}</dd><dt>付款截止</dt><dd>{{formatDate(order.expireAt)||'未提供'}}</dd><dt>完成时间</dt><dd>{{formatDate(order.finishAt)||'尚未完成'}}</dd></dl><p v-if="order.orderType===0" class="small muted">自提由门店工作人员核对取货码后核销，顾客端不提供自助核销。</p><p v-if="order.cancelReason" class="small muted">取消原因：{{order.cancelReason}}</p></section><section class="paper pad actual-totals"><h3>服务端金额明细</h3><dl class="details-list"><dt>商品金额</dt><dd>¥{{yuanMoney(order.goodsAmount)}}</dd><dt>促销优惠</dt><dd>¥{{yuanMoney(order.discountAmount)}}</dd><dt>券抵扣</dt><dd>¥{{yuanMoney(order.couponAmount)}}</dd><dt>积分抵扣</dt><dd>¥{{yuanMoney(order.pointDeductAmount)}}</dd><dt>配送费</dt><dd>¥{{yuanMoney(order.freightAmount)}}</dd></dl><div class="summary-total"><strong>实际应付</strong><span class="price">¥{{yuanMoney(order.payableAmount)}}</span></div></section></div><div v-if="localAcceptance&&capability&&canCancel(order)" class="notice-panel spaced">此实例开放测试模拟支付，不会产生真实付款；金额与状态由后端再次校验。</div><div v-else-if="canCancel(order)" class="notice-panel spaced">正式支付尚未接入。当前仅展示真实待支付状态。</div><div class="page-actions"><button v-if="canCancel(order)" class="btn" :disabled="busy" @click="askAction('cancel',order.id)">取消待付订单</button><button v-if="canMockPay(order,capability,localAcceptance)" class="btn primary" :disabled="busy" @click="askAction('simulate',order.id)">模拟支付（测试）</button><button v-if="canReceive(order)" class="btn primary" :disabled="busy" @click="askAction('receive',order.id)">确认收货</button><a class="btn" href="#orders">返回订单列表</a></div></template>
</template></template><p class="customer-foot">交易结果、价格和可售状态以服务端为准</p><div v-if="confirmation" class="modal-shade" @click.self="confirmation=null"><section class="live-dialog" role="dialog" aria-modal="true" aria-labelledby="trade-dialog-title"><div class="dialog-head"><h2 id="trade-dialog-title">{{{remove:'移除商品',cancel:'取消待付订单',receive:'确认收到商品',simulate:'测试模拟支付'}[confirmation.kind]}}</h2><button class="icon-btn" aria-label="关闭" @click="confirmation=null"><Icon name="x"/></button></div><p>{{confirmation.kind==='simulate'?'只调用本机测试模拟入口，不是真实付款。':confirmation.kind==='receive'?'请在收到配送商品后确认；结果由后端处理。':'确认执行此操作？'}}</p><div class="dialog-actions"><button class="btn" @click="confirmation=null">暂不操作</button><button class="btn primary" :disabled="busy" @click="confirmAction">确认</button></div></section></div></main></template>
